/// <summary>
/// Contract class for sales order finalization automate.
/// </summary>
[DataContractAttribute,
SysOperationContractProcessing(classStr(METSalesOrderFinalizationAutomateUIBuilder))]
class METSalesOrderFinalizationAutomateContract extends METSysOperationTaskDataContract
{
    FromDate                    fromDate;
    ToDate                      toDate;
    List                        warehouseList;
    guid                        topPickingProcessId;
    METOrderTransactionType     orderTransactionType;

}

Method.Source:
/// <summary>
/// get/set the top picking process guid id
/// </summary>
/// <param name = "_topPickingProcessId">Top picking process guid id</param>
/// <returns>Top picking process guid id</returns>
[DataMember, SysOperationControlVisibilityAttribute(false)]
public guid parmTopPickingProcessId(guid _topPickingProcessId = topPickingProcessId)
{
    topPickingProcessId = _topPickingProcessId;

    return topPickingProcessId;
}

/// <summary>
/// Warehouse parameter method
/// </summary>
/// <param name = "_warehouseList">List of warehouse</param>
/// <returns>List attributes</returns>
[DataMemberAttribute, 
SysOperationLabel("@MET:METVendDistributionMethodWarehouse"),
AifCollectionTypeAttribute('return', Types::String)]
public List parmWarehouseList(List _warehouseList = warehouseList)
{
    warehouseList = _warehouseList;

    return warehouseList;
}

/// <summary>
/// Ship from date parameter
/// </summary>
/// <param name = "_fromDate">From date parameter</param>
/// <returns>Date</returns>
[DataMemberAttribute,
SysOperationLabel("@MET:fromShipDate")]
public FromDate parmFromDate(FromDate _fromDate = fromDate)
{
    fromDate = _fromDate;

    return fromDate;
}

/// <summary>
/// To date parameter
/// </summary>
/// <param name = "_toDate">To date</param>
/// <returns>Date</returns>
[DataMemberAttribute,
SysOperationLabel("@MET:toShipDate")]
public ToDate parmToDate(ToDate _toDate = toDate)
{
    toDate = _toDate;

    return toDate;
}

/// <summary>
/// Parameter method for order transaction type
/// </summary>
/// <param name = "_orderTransactionType">Order transaction type</param>
/// <returns>METOrderTransactionType</returns>
[DataMember, SysOperationControlVisibilityAttribute(false)]
public METOrderTransactionType parmOrderTransactionType(METOrderTransactionType _orderTransactionType = orderTransactionType)
{
    orderTransactionType = _orderTransactionType;

    return orderTransactionType;

}

/// <summary>
/// Thread count method override
/// </summary>
/// <param name = "_threadCount">Thread count</param>
/// <returns>METThreadCount</returns>
[DataMember, SysOperationControlVisibilityAttribute(false)]
public METThreadCount parmThreadCount(METThreadCount _threadCount = threadCount)
{
    METThreadCount ret;

    ret = super(_threadCount);

    return ret;
}
